"""Evaluate whether declared source dependencies changed."""

import json


_MISSING = {"kind": "missing"}


def _canonical(value):
    """Return the canonical JSON representation of a JSON-compatible value."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def evaluate(request, policy):
    """Compare saved and current states of relevant declared source paths.

    A path is relevant when it is declared and not ignored by policy. Missing
    entries on either side are treated as the complete state {kind: missing}.
    Inputs are only read and are never modified.
    """
    declared = request.get("declared", [])
    ignored = set(policy.get("ignored", []))
    saved = request.get("saved", {})
    current = request.get("current", {})

    changed = []
    for path in set(declared):
        if path in ignored:
            continue
        saved_state = saved.get(path, _MISSING)
        current_state = current.get(path, _MISSING)
        if _canonical(saved_state) != _canonical(current_state):
            changed.append(path)

    changed.sort()
    return {"needs_review": bool(changed), "changed": changed}
